# ---------------------------------------------------------------------------
# ReinforcedConcreteRC class
# ---------------------------------------------------------------------------


class ReinforcedConcreteRC:
    """
    SageMath implementation of the Reinforced Concrete (RC) permutation.
    Supports three field instantiations: BLS381, BN254, and ST.
    """

    MODES = {
        "BLS381": {
            "p": int("0x73eda753299d7d483339d80809a1d80553bda402fffe5bfeffffffff00000001", _sage_const_16 ),
            "alpha_beta": (_sage_const_1 , _sage_const_3 , _sage_const_2 , _sage_const_4 ),
            "s": list(reversed([_sage_const_693 , _sage_const_696 , _sage_const_694 , _sage_const_668 , _sage_const_679 , _sage_const_695 , _sage_const_691 , _sage_const_693 , _sage_const_700 , _sage_const_688 , _sage_const_700 ,
                                  _sage_const_694 , _sage_const_701 , _sage_const_694 , _sage_const_699 , _sage_const_701 , _sage_const_701 , _sage_const_701 , _sage_const_695 , _sage_const_698 , _sage_const_697 , _sage_const_703 ,
                                  _sage_const_702 , _sage_const_691 , _sage_const_688 , _sage_const_703 , _sage_const_679 ])),
            "p_prime": _sage_const_659 ,
            "sbox_table": BLS_SBOX,
            "rc": BLS_RC,
        },
        "BN254": {
            "p": int("0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001", _sage_const_16 ),
            "alpha_beta": (_sage_const_1 , _sage_const_3 , _sage_const_2 , _sage_const_4 ),
            "s": list(reversed([_sage_const_651 , _sage_const_658 , _sage_const_656 , _sage_const_666 , _sage_const_663 , _sage_const_654 , _sage_const_668 , _sage_const_677 , _sage_const_681 , _sage_const_683 , _sage_const_669 ,
                                  _sage_const_681 , _sage_const_680 , _sage_const_677 , _sage_const_675 , _sage_const_668 , _sage_const_675 , _sage_const_683 , _sage_const_681 , _sage_const_683 , _sage_const_683 , _sage_const_655 ,
                                  _sage_const_680 , _sage_const_683 , _sage_const_667 , _sage_const_678 , _sage_const_673 ])),
            "p_prime": _sage_const_641 ,
            "sbox_table": BN_SBOX,
            "rc": BN_RC,
        },
        "ST": {
            "p": int("0x03fa000000000000000000000000000000000000000000000000000000000001", _sage_const_16 ),
            "alpha_beta": (_sage_const_1 , _sage_const_2 , _sage_const_3 , _sage_const_4 ),
            "s": [_sage_const_1024 ] * _sage_const_24  + [_sage_const_1023 ],
            "p_prime": _sage_const_1013 ,
            "sbox_table": ST_SBOX,
            "rc": ST_RC,
        },
    }

    def __init__(self, mode_name="BLS381"):
        if mode_name not in self.MODES:
            raise ValueError(f"Unknown mode '{mode_name}'. Choose from {list(self.MODES)}.")

        mode = self.MODES[mode_name]
        self.mode_name = mode_name
        self.p = mode["p"]
        self.F = GF(self.p)
        self.alpha1, self.alpha2, self.beta1, self.beta2 = map(self.F, mode["alpha_beta"])
        self.s = mode["s"]
        self.s_inverse = list(reversed(self.s))
        self.p_prime = mode["p_prime"]
        self.n = len(self.s)
        self.sbox_table = mode["sbox_table"]

        self.round_constants = [
            [self.F(mode["rc"][r][i]) for i in range(_sage_const_3 )]
            for r in range(_sage_const_8 )
        ]

        self.M = Matrix(self.F, _sage_const_3 , _sage_const_3 , [[_sage_const_2 , _sage_const_1 , _sage_const_1 ], [_sage_const_1 , _sage_const_2 , _sage_const_1 ], [_sage_const_1 , _sage_const_1 , _sage_const_2 ]])

        # Precompute basis elements 
        self.b = [prod(self.s[j] for j in range(i + _sage_const_1 , self.n)) for i in range(self.n)]

        # Sponge 
        self.r = _sage_const_2   
        self.c = _sage_const_1   
        self.d = _sage_const_2   

    def __str__(self):
        lines = [
            f"Reinforced Concrete {self.mode_name} over {self.F}",
            f"Rate = {self.r}, Capacity = {self.c}, Digest length = {self.d}",
            f"p_prime = {self.p_prime}",
            f"bucket = {self.s}",
            f"MDS =\n{self.M}",
        ]
        return "\n".join(lines)

    # ------------------------------------------------------------------
    # Decomposition / Composition
    # ------------------------------------------------------------------

    def decomp(self, x):
        coeffs = []
        remainder = int(x)
        for i in range(self.n):
            bi = _sage_const_1  if i == _sage_const_0  else prod(self.s_inverse[j] for j in range(i))
            xi = (remainder // bi) % self.s_inverse[i]
            coeffs.append(xi)
            remainder -= xi * bi
        return coeffs[::-_sage_const_1 ]

    def comp(self, digits):
        return sum(xi * bi for xi, bi in zip(digits, self.b)) % self.p

    # ------------------------------------------------------------------
    # Components
    # ------------------------------------------------------------------

    def sbox(self, xi):
        return self.sbox_table[xi] if xi < self.p_prime else xi

    def bar(self, x):
        return self.comp([self.sbox(xi) for xi in self.decomp(x)])

    def bars(self, x_tuple):
        return tuple(self.bar(xi) for xi in x_tuple)

    def bricks(self, x_tuple):
        x1, x2, x3 = x_tuple
        d = _sage_const_3  if self.mode_name == "ST" else _sage_const_5 
        y1 = x1 ** d
        y2 = x2 * (x1**_sage_const_2  + self.alpha1 * x1 + self.beta1)
        y3 = x3 * (x2**_sage_const_2  + self.alpha2 * x2 + self.beta2)
        return (y1, y2, y3)
    
    '''
    def concrete(self, j, x_tuple):
        v = vector(self.F, x_tuple)
        return tuple(self.M * v + vector(self.F, self.round_constants[j - 1]))
    '''
    
    def concrete(self, j, x_tuple):
        """Applies the linear Concrete layer. Dynamically infers the finite field."""
        R = x_tuple[_sage_const_0 ].parent()
        v = vector(R, x_tuple)
        c = vector(R, self.round_constants[j - _sage_const_1 ])
        return tuple(self.M * v + c)


    # ------------------------------------------------------------------
    # Utility
    # ------------------------------------------------------------------

    def to_hex(self, x_tuple):
        return tuple(hex(int(xi)) for xi in x_tuple)

    # ------------------------------------------------------------------
    # Full permutation
    # ------------------------------------------------------------------

    def RC(self, x_tuple, verbose=False):
        """
        Apply the full 7-round RC permutation.
        Structure: (Concrete + Bricks)^3 + (Concrete + Bars + Concrete) + (Bricks + Concrete)^3
        """
        def log(label, x):
            if verbose:
                print(f"{label}: {self.to_hex(x)}")

        log("Input state", x_tuple)
        x = self.concrete(_sage_const_1 , x_tuple);  log("After concrete 1", x)
        x = self.bricks(x);             log("After bricks 1",   x)
        x = self.concrete(_sage_const_2 , x);        log("After concrete 2", x)
        x = self.bricks(x);             log("After bricks 2",   x)
        x = self.concrete(_sage_const_3 , x);        log("After concrete 3", x)
        x = self.bricks(x);             log("After bricks 3",   x)
        x = self.concrete(_sage_const_4 , x);        log("After concrete 4", x)
        x = self.bars(x);               log("After bars",        x)
        x = self.concrete(_sage_const_5 , x);        log("After concrete 5", x)
        x = self.bricks(x);             log("After bricks 4",   x)
        x = self.concrete(_sage_const_6 , x);        log("After concrete 6", x)
        x = self.bricks(x);             log("After bricks 5",   x)
        x = self.concrete(_sage_const_7 , x);        log("After concrete 7", x)
        x = self.bricks(x);             log("After bricks 6",   x)
        x = self.concrete(_sage_const_8 , x);        log("After concrete 8", x)
        return x

    # ------------------------------------------------------------------
    # Reduced-round variants
    # ------------------------------------------------------------------

    def RC_round_last_concrete(self, x_tuple, r0, r1, verbose=False):
        """
        Reduced-round permutation ending with a Concrete layer.
        Structure: (Concrete + Bricks)^r0 + (Concrete + Bars + Concrete) + (Bricks + Concrete)^r1
        Requires r0 + r1 <= 6.
        """
        assert r0 + r1 <= _sage_const_6 , "r0 + r1 must be at most 6"
        if verbose:
            print(f"Instance: (Concrete+Bricks)*{r0} + (Concrete + Bars + Concrete)+ (Bricks+Concrete)*{r1}")

        x = x_tuple
        for r in range(r0):
            x = self.concrete(r + _sage_const_1 , x)
            x = self.bricks(x)
        x = self.concrete(r0 + _sage_const_1 , x)
        x = self.bars(x)
        x = self.concrete(r0 + _sage_const_2 , x)
        for r in range(r1):
            x = self.bricks(x)
            x = self.concrete(r0 + _sage_const_3  + r, x)
        return x

    def RC_round_last_bricks(self, x_tuple, r0, r1, verbose=False):
        """
        Reduced-round permutation ending with a Bricks layer.
        Structure: (Concrete + Bricks)^r0 + (Concrete + Bars + Concrete) + (Bricks + Concrete)^(r1) + Bricks
        Requires r0 + r1 <= 6.
        """
        assert r0 + r1 <= _sage_const_6 , "r0 + r1 must be at most 6"
        if verbose:
            print(f"\n[*] Instance: (Concrete+Bricks)*{r0} + (Concrete + Bars + Concrete) + (Bricks+Concrete)*{r1} + Bricks")

        x = x_tuple
        for r in range(r0):
            x = self.concrete(r + _sage_const_1 , x)
            x = self.bricks(x)
        x = self.concrete(r0 + _sage_const_1 , x)
        x = self.bars(x)
        x = self.concrete(r0 + _sage_const_2 , x)
        for r in range(r1 - _sage_const_1 ):
            x = self.bricks(x)
            x = self.concrete(r0 + _sage_const_3  + r, x)
        x = self.bricks(x)
        return x

    def RC_round_diff(self, x0_tuple, x1_tuple, r0, verbose=False):
        """
        Structure: (Concrete + Bricks)^r0 
        """
        assert r0 <= _sage_const_3 , "r0 must be at most 3"
        if verbose:
            print(f"\n[*] Instance: (Concrete+Bricks)*{r0}")

        x0 = x0_tuple
        x1 = x1_tuple

        dx = [self.F(_sage_const_0 ) for i in range(_sage_const_3 )]
    
        for r in range(r0-_sage_const_1 ):
            x0 = self.concrete(r + _sage_const_1 , x0)
            x1 = self.concrete(r + _sage_const_1 , x1)

            x0 = self.bricks(x0)
            x1 = self.bricks(x1)
        
        x0 = self.concrete(r0, x0)
        x1 = self.concrete(r0, x1)

        dx[_sage_const_0 ] = x1[_sage_const_0 ]-x0[_sage_const_0 ]

        x0 = self.bricks(x0)
        x1 = self.bricks(x1)

        dx[_sage_const_1 ] = x1[_sage_const_1 ]-x0[_sage_const_1 ]
        dx[_sage_const_2 ] = x1[_sage_const_2 ]-x0[_sage_const_2 ]
 
        return tuple(dx)


    # ------------------------------------------------------------------
    # Equation Generation for Cryptanalysis
    # ------------------------------------------------------------------
    
    def generate_rc_system(self,r0):

        P = PolynomialRing(self.F, names=['m1', 'm2', 'dm1'])
        m1, m2, dm1 = P.gens()

        x0 = (m1,       m2,         P(_sage_const_0 ))
        x1 = (m1 + dm1, m2 - _sage_const_2 *dm1, P(_sage_const_0 ))

        differences = {}

        for r in range(_sage_const_1 , r0 + _sage_const_1 ):
            # Apply Concrete Layer
            x0 = self.concrete(r, x0)
            x1 = self.concrete(r, x1)
            differences[f"R{r}_AfterConcrete"] = tuple(b - a for a, b in zip(x0, x1))

            # Apply Bricks Layer
            x0 = self.bricks(x0)
            x1 = self.bricks(x1)
            # Store the difference
            differences[f"R{r}_AfterBricks"] = tuple(b - a for a, b in zip(x0, x1))

        return P, differences

